    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "व्यालं बाणमृणालतन्तुभिरसौ रोद्धुं समुज्जृम्भते",
          "end": "line"
        },
        {
          "n": 2,
          "text": "छेत्तुं[१] वज्रमणीञ्शिरीषकुसुमप्रान्तेन संनह्यते ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "माधुर्यं मधुबिन्दुना रचयितुं क्षाराम्बुधेरीहते",
          "end": "line"
        },
        {
          "n": 4,
          "text": "नेतुं वाञ्छति[२] यः खलान्पथि सतां सूक्तैः सुधास्यन्दिभिः॥६॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "असौ नरः व्यालं दुष्टगजम् । व्यालो दुष्टगजे सर्पे इति विश्वमेदिन्यौ ।",
          "end": "space"
        },
        {
          "n": 2,
          "text": "बालं च तन्मृणालं बिसं तस्य तन्तुभिः । रोद्धुं नियन्तुमुज्जृम्भते । कृतोत्साहो",
          "end": "space"
        },
        {
          "n": 3,
          "text": "भवति । वज्रो हीरकः मणिः वज्रमणिस्तम् । तीक्ष्णलोहेनानालेख्यमपीत्यर्थः ।",
          "end": "space"
        },
        {
          "n": 4,
          "text": "शिरीषकुसुमं सर्वेषु कुसुमेषु म्रदिष्ठं तस्य प्रान्तेन । प्रकृष्टोन्तः प्रान्तस्तेन । छेत्तुं",
          "end": "space"
        },
        {
          "n": 5,
          "text": "सन्नह्यते बद्धपरिकरो भवति । क्षारश्चासावम्बुधिश्च तस्य । मधुरातीति मधुरं",
          "end": "space"
        },
        {
          "n": 6,
          "text": "मधुरस्य भावो माधुर्यं तत् । ईहते वाञ्छति । क इत्याकांक्षायामाह—यः । सुधां",
          "end": "space"
        },
        {
          "n": 7,
          "text": "स्यन्दन्ते तच्छीलैः अमृतस्राविभिः सूक्तैः प्रियभाषणैः । स्पष्टमन्यत् । मूर्खं यः",
          "end": "space"
        },
        {
          "n": 8,
          "text": "प्रतिनेतुमित्यादिपाठे प्रतिनेतुमनुनेतुमित्यर्थः । अलंकारो मालानिदर्शना । न",
          "end": "space"
        },
        {
          "n": 9,
          "text": "चायं दृष्टान्तः । वाक्यभेदेन प्रतिबिम्बकरणाक्षेपे तस्योत्थानात् । अत्र तु वा-",
          "end": "hyphen"
        },
        {
          "n": 10,
          "text": "क्यार्थे वाक्यार्थसमारोपाद्वाक्यस्यैकवाक्यतायां तदभाव इत्यलंकारसर्वस्वकारः ।",
          "end": "space"
        },
        {
          "n": 11,
          "text": "शार्दूलविक्रीडितं वृत्तम् ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "स्वायत्तमेकान्तगुणं[३] विधात्रा विनिर्मितं छादनमज्ञतायाः ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "विशेषतः सर्वविदां समाजे विभूषणं मौनमपण्डितानाम् ॥७॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "स्वस्यायत्तं स्वायत्तं स्वाधीनं न त्वन्यापेक्षम् । एक एवान्तो यस्य स एकान्तः ।",
          "end": "space"
        },
        {
          "n": 2,
          "text": "एकान्तो गुणो यस्य तत् । एतादृग् अज्ञतायाः । छाद्यतेऽनेनेति छादनम् ।",
          "end": "space"
        },
        {
          "n": 3,
          "text": "करणाधिकरणयोश्च (पा. ३. ३. ११७) इति करणे ल्युट् । विधात्रा निर्मितम् ।",
          "end": "space"
        },
        {
          "n": 4,
          "text": "किं तदित्यापेक्षायामाह—मौनमिति । कथंभूतं विशेषतः सर्वे विदन्तीति",
          "end": "space"
        },
        {
          "n": 5,
          "text": "सर्वविदस्तेषां समाजे । अपण्डितानां भूषणम् । पण्डा सदसद्विवेकबुद्धिः ।",
          "end": "space"
        },
        {
          "n": 6,
          "text": "पण्डा एषां सञ्जाता इति पण्डिताः । तदस्य सञ्जातमिति तारकादिभ्य इतच्",
          "end": "space"
        },
        {
          "n": 7,
          "text": "( पा. ५. २. ३६ ) इति इतच्प्रत्ययः । न पण्डिता अपण्डितास्तेषाम् । अतः",
          "end": "space"
        },
        {
          "n": 8,
          "text": "सर्वत्र विशेषतः पण्डितसभासु अज्ञैर्मौनमाश्रित्य वर्तितव्यमिति भावः । उपजा-",
          "end": "hyphen"
        },
        {
          "n": 9,
          "text": "तिच्छन्दः ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
